    14	import org.springframework.stereotype.Service;
    15	import org.springframework.transaction.annotation.Transactional;
    16	
    17	import java.time.LocalDate;
    18	
    19	@Service
    20	@Transactional
    21	public class LoanBookService implements LoanBookUseCase {
    22	
    23	    private final LoadMemberPort loadMemberPort;
    24	    private final LoadBookPort loadBookPort;
    25	    private final SaveBookPort saveBookPort;
