    28	
    29	    public LoanBookService(LoadMemberPort loadMemberPort, LoadBookPort loadBookPort, SaveBookPort saveBookPort,
    30	                           LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort) {
    31	        this.loadMemberPort = loadMemberPort;
    32	        this.loadBookPort = loadBookPort;
    33	        this.saveBookPort = saveBookPort;
    34	        this.loadLoanPort = loadLoanPort;
    35	        this.saveLoanPort = saveLoanPort;
    36	    }
    37	
    38	    @Override
    39	    public Loan loanBook(LoanBookCommand command) {
    40	        Member member = loadMemberPort.loadMember(command.memberId())
    41	                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
    42	        Book book = loadBookPort.loadBook(command.bookId())
    43	                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
    44	        member.ensureCanBorrow(loadLoanPort.countLoansByMemberId(member.getId()));
    45	        Loan loan = book.loanTo(member.getId(), LocalDate.now());
    46	        saveBookPort.saveBook(book);
    47	        saveLoanPort.saveLoan(loan);
    48	        return loan;
    49	    }
    50	}
